public class BasicSerializerFactory_findSerializerByPrimaryType_TriageGen1Test {

    private BasicSerializerFactory factory;
    private SerializerProvider prov;
    private BeanDescription beanDesc;
    private SerializationConfig config;
    private TypeFactory typeFactory;

    // Subclass to expose protected method for testing
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        protected TestableBasicSerializerFactory(SerializerFactoryConfig config) {
            super(config);
        }

        @Override
        public JsonSerializer<Object> createSerializer(SerializerProvider prov, JavaType type) throws JsonMappingException {
            return null;
        }

        @Override
        protected Iterable<Serializers> customSerializers() {
            return null;
        }

        @Override
        protected SerializerFactory withConfig(SerializerFactoryConfig config) {
            return this;
        }

        @Override
        public JsonSerializer<?> callFindSerializerByPrimaryType(SerializerProvider prov, JavaType type, BeanDescription beanDesc, boolean staticTyping) throws JsonMappingException {
            return findSerializerByPrimaryType(prov, type, beanDesc, staticTyping);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicSerializerFactory(null);
        prov = mock(SerializerProvider.class);
        beanDesc = mock(BeanDescription.class);
        config = mock(SerializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();

        when(prov.getConfig()).thenReturn(config);
    }

    @Test
    public void testFindOptionalStdSerializer_ReturnsNonNull() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);

        // Mocking the behavior of findOptionalStdSerializer via spy or partial mock is hard because it's a real method in the class.
        // However, in a real Jackson environment, this would be triggered by registered serializers.
        // For this test, we assume the method logic: if findOptionalStdSerializer returns non-null, we return it.
        // Since we cannot easily mock the protected method inside the same object without a spy, 
        // we rely on the fact that if we can't override it, we test the other branches.
        // To test the "if (ser != null)" branch, we would need to spy the factory.

        TestableBasicSerializerFactory spyFactory = spy(factory);
        doReturn(mockSer).when(spyFactory).findOptionalStdSerializer(any(), any(), any(), anyBoolean());

        JsonSerializer<?> result = spyFactory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testCalendarSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Calendar.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(CalendarSerializer.instance, result);
    }

    @Test
    public void testDateSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Date.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(DateSerializer.instance, result);
    }

    @Test
    public void testMapEntrySerializer() throws JsonMappingException {
        // Map.Entry<String, Integer>
        JavaType type = typeFactory.constructType(Map.Entry.class);
        // We need to provide contained types for Map.Entry to avoid unknownType logic if possible, 
        // but the code handles null kt/vt.

        // To test buildMapEntrySerializer, we need to mock the factory to return a value or just check it doesn't crash
        // Since buildMapEntrySerializer is protected, we check if it calls it.
        TestableBasicSerializerFactory spyFactory = spy(factory);
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(spyFactory).buildMapEntrySerializer(any(), any(), any(), anyBoolean(), any(), any());

        JsonSerializer<?> result = spyFactory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testByteBufferSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(ByteBuffer.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertTrue(result instanceof ByteBufferSerializer);
    }

    @Test
    public void testInetAddressSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetAddress.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertTrue(result instanceof InetAddressSerializer);
    }

    @Test
    public void testInetSocketAddressSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetSocketAddress.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertTrue(result instanceof InetSocketAddressSerializer);
    }

    @Test
    public void testTimeZoneSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(TimeZone.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertTrue(result instanceof TimeZoneSerializer);
    }

    @Test
    public void testCharsetSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Charset.class);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberSerializer_Default() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        when(beanDesc.findExpectedFormat(null)).thenReturn(null);
        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(NumberSerializer.instance, result);
    }

    @Test
    public void testNumberSerializer_AsStringFormat() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberSerializer_AsObjectFormat_ReturnsNull() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }

    @Test
    public void testNumberSerializer_AsArrayFormat_ReturnsNull() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.ARRAY);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }

    @Test
    public void testEnumSerializer() throws JsonMappingException {
        enum TestEnum { A, B }
        JavaType type = typeFactory.constructType(TestEnum.class);

        TestableBasicSerializerFactory spyFactory = spy(factory);
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(spyFactory).buildEnumSerializer(any(), any(), any());

        JsonSerializer<?> result = spyFactory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testUnknownType_ReturnsNull() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Object.class);
        // Ensure no optional serializer is found
        TestableBasicSerializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory).findOptionalStdSerializer(any(), any(), any(), anyBoolean());

        JsonSerializer<?> result = spyFactory.callFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }
}
